use std::collections::BTreeMap;
use std::io::{self, BufRead, Write};

fn parse_record(line: &str) -> Option<(&str, u64)> {
    let (category, value) = line.split_once(',')?;
    if category.is_empty()
        || !category.bytes().all(|byte| byte.is_ascii_alphanumeric())
        || value.is_empty()
        || !value.bytes().all(|byte| byte.is_ascii_digit())
    {
        return None;
    }

    // split_once allows additional delimiters in the value, rejected by the digit check.
    let value = value.parse().ok()?;
    Some((category, value))
}

fn run<R: BufRead, W: Write, E: Write>(input: R, output: &mut W, error: &mut E) -> io::Result<()> {
    let mut totals = BTreeMap::<String, u64>::new();
    let mut skipped = 0_u64;

    for line in input.lines() {
        let line = line?;
        match parse_record(&line) {
            Some((category, value)) => {
                let total = totals.entry(category.to_owned()).or_default();
                *total = total
                    .checked_add(value)
                    .ok_or_else(|| io::Error::other("category total overflow"))?;
            }
            None => {
                skipped = skipped
                    .checked_add(1)
                    .ok_or_else(|| io::Error::other("malformed line count overflow"))?;
            }
        }
    }

    for (category, total) in totals {
        writeln!(output, "{category},{total}")?;
    }
    writeln!(error, "skipped={skipped}")?;
    Ok(())
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let stderr = io::stderr();

    if let Err(err) = run(stdin.lock(), &mut stdout.lock(), &mut stderr.lock()) {
        let _ = writeln!(io::stderr().lock(), "{err}");
        std::process::exit(1);
    }
}

