use std::collections::BTreeMap;
use std::io::{self, BufRead, Write};

fn parse_record(line: &[u8]) -> Option<(&[u8], u64)> {
    let comma = line.iter().position(|&byte| byte == b',')?;
    if line[comma + 1..].contains(&b',') {
        return None;
    }

    let category = &line[..comma];
    let number = &line[comma + 1..];
    if category.is_empty()
        || !category
            .iter()
            .all(|byte| byte.is_ascii_alphanumeric())
        || number.is_empty()
        || !number.iter().all(u8::is_ascii_digit)
    {
        return None;
    }

    let number = std::str::from_utf8(number).ok()?.parse::<u64>().ok()?;
    Some((category, number))
}

fn run<R: BufRead, O: Write, E: Write>(
    mut input: R,
    mut output: O,
    mut error: E,
) -> io::Result<()> {
    let mut totals: BTreeMap<Vec<u8>, u64> = BTreeMap::new();
    let mut skipped = 0u64;
    let mut line = Vec::new();

    loop {
        line.clear();
        if input.read_until(b'\n', &mut line)? == 0 {
            break;
        }
        if line.last() == Some(&b'\n') {
            line.pop();
        }

        match parse_record(&line) {
            Some((category, value)) => {
                let total = totals.entry(category.to_vec()).or_insert(0);
                *total = total.checked_add(value).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::Other, "category total overflow")
                })?;
            }
            None => {
                skipped = skipped.checked_add(1).ok_or_else(|| {
                    io::Error::new(io::ErrorKind::Other, "malformed line count overflow")
                })?;
            }
        }
    }

    for (category, total) in totals {
        output.write_all(&category)?;
        writeln!(output, ",{total}")?;
    }
    writeln!(error, "skipped={skipped}")?;
    Ok(())
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    let stderr = io::stderr();
    if let Err(err) = run(stdin.lock(), stdout.lock(), stderr.lock()) {
        eprintln!("{err}");
        std::process::exit(1);
    }
}

