use std::collections::BTreeMap;
use std::io::{self, BufRead, Write};

fn parse_line(line: &str) -> Option<(&str, u64)> {
    let (category, value) = line.split_once(',')?;
    if category.is_empty()
        || !category.bytes().all(|byte| byte.is_ascii_alphanumeric())
        || value.is_empty()
        || !value.bytes().all(|byte| byte.is_ascii_digit())
    {
        return None;
    }

    // The digit check above restricts parsing to unsigned ASCII decimal syntax.
    let value = value.parse().ok()?;
    Some((category, value))
}

fn collect_totals<R: BufRead>(reader: R) -> io::Result<(BTreeMap<String, u64>, usize)> {
    let mut totals = BTreeMap::new();
    let mut skipped = 0;

    for line in reader.lines() {
        let line = line?;
        let Some((category, value)) = parse_line(&line) else {
            skipped += 1;
            continue;
        };

        let total = totals.entry(category.to_owned()).or_insert(0_u64);
        *total = total.checked_add(value).ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                format!("total overflow for category {category}"),
            )
        })?;
    }

    Ok((totals, skipped))
}

fn run<R: BufRead, W: Write, E: Write>(reader: R, mut stdout: W, mut stderr: E) -> io::Result<()> {
    let (totals, skipped) = collect_totals(reader)?;
    for (category, total) in totals {
        writeln!(stdout, "{category},{total}")?;
    }
    writeln!(stderr, "skipped={skipped}")?;
    Ok(())
}

fn main() {
    if let Err(error) = run(io::stdin().lock(), io::stdout().lock(), io::stderr().lock()) {
        let _ = writeln!(io::stderr().lock(), "error: {error}");
        std::process::exit(1);
    }
}

