//! A parser for versions containing exactly three decimal `u16` components.

use std::fmt;
use std::str::FromStr;

/// A version with major, minor, and patch components.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub struct Version {
    major: u16,
    minor: u16,
    patch: u16,
}

impl Version {
    /// Returns the major component.
    pub const fn major(&self) -> u16 {
        self.major
    }

    /// Returns the minor component.
    pub const fn minor(&self) -> u16 {
        self.minor
    }

    /// Returns the patch component.
    pub const fn patch(&self) -> u16 {
        self.patch
    }
}

/// The reason a string could not be parsed as a [`Version`].
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ParseVersionError {
    /// The input did not contain exactly three components.
    InvalidComponentCount,
    /// A component was empty, had a leading zero, or contained a non-ASCII digit.
    InvalidComponent,
    /// A component was greater than `u16::MAX`.
    ComponentOutOfRange,
}

impl fmt::Display for ParseVersionError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidComponentCount => {
                f.write_str("version must have exactly three components")
            }
            Self::InvalidComponent => f.write_str(
                "version components must be ASCII decimal digits without leading zeroes",
            ),
            Self::ComponentOutOfRange => f.write_str("version component exceeds u16::MAX"),
        }
    }
}

impl std::error::Error for ParseVersionError {}

impl FromStr for Version {
    type Err = ParseVersionError;

    fn from_str(input: &str) -> Result<Self, Self::Err> {
        let mut components = input.split('.');
        let major = parse_component(components.next().unwrap_or_default())?;
        let minor = parse_component(components.next().unwrap_or_default())?;
        let patch = parse_component(components.next().unwrap_or_default())?;
        if components.next().is_some() {
            return Err(ParseVersionError::InvalidComponentCount);
        }
        Ok(Self {
            major,
            minor,
            patch,
        })
    }
}

fn parse_component(component: &str) -> Result<u16, ParseVersionError> {
    if component.is_empty()
        || (component.len() > 1 && component.starts_with('0'))
        || !component.bytes().all(|byte| byte.is_ascii_digit())
    {
        return Err(ParseVersionError::InvalidComponent);
    }
    component
        .parse()
        .map_err(|_| ParseVersionError::ComponentOutOfRange)
}

#[cfg(test)]
mod tests {
    use super::{ParseVersionError, Version};
    use std::str::FromStr;

    #[test]
    fn parses_components_and_u16_boundaries() {
        let version = Version::from_str("0.42.65535").unwrap();
        assert_eq!(
            (version.major(), version.minor(), version.patch()),
            (0, 42, 65535)
        );
        assert_eq!("65535.0.1".parse::<Version>().unwrap().major(), u16::MAX);
    }

    #[test]
    fn rejects_malformed_inputs() {
        for input in [
            "", ".1.2", "1..2", "1.2.", "1.2", "1.2.3.4", " 1.2.3", "1.2.3 ", "+1.2.3", "-1.2.3",
            "01.2.3", "1.02.3", "1.2.03", "١.2.3",
        ] {
            assert!(input.parse::<Version>().is_err(), "accepted {input:?}");
        }
    }

    #[test]
    fn distinguishes_overflow() {
        assert_eq!(
            "65536.0.0".parse::<Version>(),
            Err(ParseVersionError::ComponentOutOfRange)
        );
        assert_eq!(
            "1.2.99999".parse::<Version>(),
            Err(ParseVersionError::ComponentOutOfRange)
        );
    }
}

