//! A small parser for versions made of exactly three decimal `u16` components.

use std::error::Error;
use std::fmt;
use std::str::FromStr;

/// A version consisting of a major, minor, and patch component.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Version {
    major: u16,
    minor: u16,
    patch: u16,
}

impl Version {
    /// Returns the major component.
    pub const fn major(&self) -> u16 {
        self.major
    }

    /// Returns the minor component.
    pub const fn minor(&self) -> u16 {
        self.minor
    }

    /// Returns the patch component.
    pub const fn patch(&self) -> u16 {
        self.patch
    }
}

/// Reasons a string is not a valid three-component version.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ParseVersionError {
    /// The input does not contain exactly three dot-separated components.
    InvalidComponentCount,
    /// A component is empty or contains something other than ASCII digits.
    InvalidComponent,
    /// A component has a leading zero and contains more than one digit.
    LeadingZero,
    /// A component is greater than `u16::MAX`.
    ComponentOverflow,
}

impl fmt::Display for ParseVersionError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidComponentCount => f.write_str("version must have exactly three components"),
            Self::InvalidComponent => f.write_str("components must contain only ASCII decimal digits"),
            Self::LeadingZero => f.write_str("components must not have leading zeroes"),
            Self::ComponentOverflow => f.write_str("component does not fit in u16"),
        }
    }
}

impl Error for ParseVersionError {}

impl FromStr for Version {
    type Err = ParseVersionError;

    fn from_str(input: &str) -> Result<Self, Self::Err> {
        let mut components = input.split('.');
        let major = parse_component(components.next().unwrap_or_default())?;
        let minor = parse_component(components.next().unwrap_or_default())?;
        let patch = parse_component(components.next().unwrap_or_default())?;
        if components.next().is_some() {
            return Err(ParseVersionError::InvalidComponentCount);
        }

        Ok(Self { major, minor, patch })
    }
}

fn parse_component(component: &str) -> Result<u16, ParseVersionError> {
    if component.is_empty() || !component.bytes().all(|byte| byte.is_ascii_digit()) {
        return Err(ParseVersionError::InvalidComponent);
    }
    if component.len() > 1 && component.starts_with('0') {
        return Err(ParseVersionError::LeadingZero);
    }
    component
        .parse()
        .map_err(|_| ParseVersionError::ComponentOverflow)
}

